ueda":"PARACETAMOL"},{"registro_isp":"F-8663/26","nombre":"PARACETAMOL + MEPIRAMINA MALEATO + PAMABRON COMPRIMIDOS","fecha_registro_isp":"2001-06-26","titular":"INSTITUTO SANITAS S.A.","principio_activo":"MEPIRAMINA//PAMABRON//PARACETAMOL","control_legal":null,"estado":"Vigente","busqueda":"PARACETAMOL"}]$isp_catalogo$::jsonb) AS x(registro_isp text,nombre text,fecha_registro_isp date,titular text,principio_activo text,control_legal text,estado text,busqueda text)
), nuevos AS (
 INSERT INTO public.producto(nombre,descripcion,codigo_barras,unidad_medida,id_categoria,principio_activo,registro_isp,vida_util_meses,titular_isp,fecha_registro_isp,estado_registro_isp,fuente_isp,fecha_consulta_isp,importado_isp_en)
 SELECT o.nombre,'Registro sanitario ISP. Confirmar presentación y GTIN en el envase.',NULL,NULL,
 (SELECT min(id_categoria) FROM public.categoria WHERE nombre='Catálogo ISP'),o.principio_activo,o.registro_isp,NULL,o.titular,o.fecha_registro_isp,o.estado,'https://registrosanitario.ispch.gob.cl/','2026-10-27'::date,now()
 FROM origen o WHERE NOT EXISTS(SELECT 1 FROM public.producto p WHERE upper(trim(p.registro_isp))=o.registro_isp)
 RETURNING id_producto
)
SELECT count(*) AS productos_agregados FROM nuevos;
COMMIT;
